insert into public.reviews (id,negocio_id,nombre,puntuacion,texto,fecha,estado) values
('00000000-0000-4000-8000-000000000001','1','Lucía M.',5,'Un lugar hermoso para una cena tranquila. Muy buena atención y platos con mucho sabor. ¡Volveríamos!','2026-09-18','aprobado'),
('00000000-0000-4000-8000-000000000002','1','Martín R.',4,'Nos encantó el ambiente y la propuesta de estación. Ideal para una sobremesa sin apuro.','2026-09-12','aprobado'),
('00000000-0000-4000-8000-000000000003','2','Paula G.',5,'El café y la pastelería fueron lo mejor de nuestra tarde. Muy lindo el patio.','2026-09-20','aprobado')
